import initialState from "../../helpers/initialState";

const state = {
  dialog: {
    addEditLink: false
  },
  action: "add",
  index: -1,
  item: initialState("home").item,
  items: []
};

const getters = {};

const actions = {
  _getLinks({ commit }) {
    chrome.storage.sync.get(["newTab"], res => {
      if (res.newTab === undefined) {
        chrome.topSites.get(items => {
          chrome.storage.sync.set({ newTab: JSON.stringify(items) }, function() {
            commit("_getLinks", items);
          });
        });
      } else {
        commit("_getLinks", JSON.parse(res.newTab));
      }
      //console.log(items);
    });
  },
  _addLink({ commit }) {
    commit("_addLink");
  },

  _showLink({ commit }, item) {
    commit("_showLink", item);
  },
  _editLink({ commit }) {
    commit("_editLink");
  },
  _deleteLink({ commit }) {
    commit("_deleteLink");
  },
  _orderLinks({ commit }, links) {
    commit("_orderLinks", links);
  },
  toggleDialog({ commit }, key) {
    commit("toggleDialog", key);
  },
  _reset({ commit }, key = null) {
    commit("_reset", key);
  }
};

const mutations = {
  _getLinks(state, items) {
    state.items = items;
  },
  _addLink() {
    state.items.push(state.item);

    storageLinks(state.items);
  },
  _showLink(state, item) {
    state.action = "edit";
    state.index = state.items.indexOf(item);
    state.item = Object.assign(state.item, item);
  },
  _editLink(state) {
    //state.items[state.index] = state.item;
    //console.log(state.index);
    this._vm.$set(state.items, state.index, state.item);
    storageLinks(state.items);

    //console.log(state.items);
  },
  _deleteLink(state) {
    state.items.splice(state.index, 1);

    //despues de eliminar un enlaces, guardamos en chrome los enlaces que quedaron
    storageLinks(state.items);
  },
  _orderLinks(state, links) {},
  toggleDialog(state, key) {
    state.dialog[key] = !state.dialog[key];
  },
  _reset(state, key) {
    setTimeout(() => {
      state.action = "add";
      state.item = initialState("home").item;
      state.index = -1;
    }, 150);
  }
};

//funciones extras

function storageLinks(items) {
  chrome.storage.sync.set(
    {
      newTab: JSON.stringify(items)
    },
    function() {}
  );
}

export default {
  state,
  getters,
  actions,
  mutations,
  namespaced: true
};
