<template>
  <v-dialog width="380" v-model="dialog" persistent>
    <v-card class="px-6 pb-4">
      <v-card-title class="px-0 subtitle-1">{{
        action === "add" ? "Agregar un acceso directo" : "Editar acceso directo"
      }}</v-card-title>

      <v-card-text class="px-0">
        <form autocomplete="off">
          <div class="mb-3">
            <label for="" class="caption">Nombre</label>
            <v-text-field
              filled
              dense
              hide-details
              v-model="item.title"
            ></v-text-field>
          </div>
          <div class="mb-3">
            <label for="" class="caption">URL</label>
            <v-text-field
              filled
              dense
              hide-details
              v-model="item.url"
            ></v-text-field>
          </div>
        </form>
      </v-card-text>

      <v-card-actions class="px-0">
        <v-btn
          outlined
          class="btn-dense"
          :disabled="action === 'add'"
          @click="remove"
        >
          Quitar
        </v-btn>
        <v-spacer />
        <v-btn outlined class="btn-dense" color="primary" @click="cancel"
          >Cancelar</v-btn
        >
        <v-btn class="btn-dense" color="primary" depressed @click="save"
          >Listo</v-btn
        >
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>

<script>
import { mapState, mapActions } from "vuex";
export default {
  computed: {
    ...mapState({
      dialog: state => state.home.dialog.addEditLink,
      action: state => state.home.action,
      item: state => state.home.item
    })
  },
  methods: {
    ...mapActions("home", [
      "_addLink",
      "_editLink",
      "toggleDialog",
      "_reset",
      "_deleteLink"
    ]),
    save() {
      if (this.action === "add") {
        this._addLink();
      } else {
        this._editLink();
      }
      this.closeDialog();
    },
    cancel() {
      this.closeDialog();
    },
    remove() {
      this._deleteLink();
      this.closeDialog();
    },
    closeDialog() {
      this.toggleDialog("addEditLink");
      this._reset();
    }
  }
};
</script>

