<template>
  <v-card width="112" height="112" class="mb-5 item-quicklink elevation-0">
    <span class="ql-menu pa-1" @click="openDialog" v-if="!hideMenu">
      <v-icon>mdi-dots-vertical</v-icon>
    </span>
    <v-card
      :tag="tag"
      :href="href"
      elevation="0"
      color="transparent"
      :ripple="false"
      height="112"
    >
      <v-card-text>
        <slot>
          <span class="icon-circle mx-auto">
            <img
              :src="'chrome://favicon/size/48/' + item.url"
              width="20"
              alt="image"
            />
          </span>
          <div class="text-truncate mt-4 text-center">
            {{ item.title }}
          </div>
        </slot>
      </v-card-text>
    </v-card>
  </v-card>
</template>

<script>
import { mapActions } from "vuex";
export default {
  props: {
    tag: {
      type: String,
      default: "div"
    },
    hideMenu: {
      type: Boolean,
      default: false
    },
    href: {
      type: String,
      default: null
    },
    item: {
      type: Array,
      default: () => []
    }
  },
  methods: {
    ...mapActions("home", ["toggleDialog", "_showLink"]),
    openDialog() {
      this.toggleDialog("addEditLink");
      this._showLink(this.item);
    }
  }
};
</script>

