<template>
  <v-app>
    <v-content>
      <div id="main" class="d-flex justify-center align-center flex-wrap">
        <div class="w-100">
          <GoogleSearch />
          <QuickLinks />
        </div>
      </div>
    </v-content>
    <AddEditLink />
  </v-app>
</template>

<script>
import GoogleSearch from "./components/home/GoogleSearch";
import QuickLinks from "./components/home/QuickLinks";
import AddEditLink from "./components/home/AddEditLink";

export default {
  name: "App",
  components: {
    GoogleSearch,
    QuickLinks,
    AddEditLink
  },
  methods: {
    activateDarkMode() {
      this.$vuetify.theme.dark = true;
    },
    activateLightMode() {
      this.$vuetify.theme.dark = false;
    },
    osTheme() {
      const darkMode = window.matchMedia("(prefers-color-scheme: dark)");
      const lightMode = window.matchMedia("(prefers-color-scheme: light)");

      darkMode.addListener(e => e.matches && this.activateDarkMode());
      lightMode.addListener(e => e.matches && this.activateLightMode());

      if (darkMode.matches) {
        this.activateDarkMode();
      } else {
        this.activateLightMode();
      }
    }
  },
  created() {
    this.osTheme();
  }
};
</script>
