<template>
  <div>
    <div id="logo" class="mx-auto mb-10"></div>
    <div id="search" class="mx-auto">
      <form @submit.prevent="onSubmit">
        <button class="search-icon-search">
          <v-icon>mdi-magnify</v-icon>
        </button>
        <input
          type="text"
          placeholder="Buscar en google"
          required
          v-model="value"
        />
      </form>
    </div>
  </div>
</template>

<script>
import isUrl from "is-valid-http-url";
export default {
  data() {
    return {
      value: null
    };
  },
  methods: {
    onSubmit() {
      if (isUrl(this.value)) {
        window.location.href = this.value;
        //is url
      } else {
        //console.log("not");
        //not is url
        window.location.href = "https://google.com/search?q=" + this.value;
      }
    }
  }
};
</script>

