<template>
  <div id="quick-links" class="mx-auto mt-10 ">
    <draggable
      :list="links"
      @end="onEnd"
      @start="onStart"
      v-bind="dragOptions"
      class="d-flex flex-wrap align-center justify-center"
    >
      <ItemLink
        tag="a"
        :href="link.url"
        v-for="link in links"
        :key="link.title"
        :item="link"
        class="item-draggable"
      />
      <ItemLink
        tag="div"
        hideMenu
        @click.native="toggleDialog('addEditLink')"
        class="cursor-pointer"
        v-if="links.length <= 9"
      >
        <span class="icon-circle mx-auto">
          <v-icon size="25">mdi-plus</v-icon>
        </span>
        <div class="text-truncate mt-4">
          Agregar un acceso directo
        </div>
      </ItemLink>
    </draggable>

    <!-- agregar nuevo acceso directo -->
  </div>
</template>

<script>
import ItemLink from "./ItemLink";
import draggable from "vuedraggable";

import { mapActions, mapState } from "vuex";
export default {
  components: {
    ItemLink,
    draggable
  },
  data() {
    return {
      drag: false
    };
  },
  computed: {
    ...mapState({
      links: state => state.home.items
    }),
    dragOptions() {
      return {
        animation: 200,
        group: "description",
        disabled: false,
        ghostClass: "ghost",
        draggable: ".item-draggable"
      };
    }
  },
  methods: {
    ...mapActions("home", ["toggleDialog", "_getLinks", "_orderLinks"]),
    onStart() {
      this.drag = true;
    },
    onEnd() {
      this._orderLinks(this.links);
      this.drag = false;
    }
  },
  created() {
    this._getLinks();
  }
};
</script>

